const versions=[{name:'The first evaluator.',label:'v0 / CNN FOUNDATION',text:'A neural starting point: the CNN checkpoint, its evaluator, Python search, and a UCI adapter. The engine keeps its model and encoding together, while training lives in its own repository.',points:['CNN checkpoint: checkpoints/kittenfish.pt','Python UCI adapter with startpos, FEN, and move history','Clock allocation, fixed time/depth, and a legal fallback move','Training source preserved in kittenfishtraining/v0'],repo:'kittenfishv0'},{name:'A deeper network.',label:'v0.5 / L4 SE-RESNET',text:'The next generation introduces an L4 SE-ResNet checkpoint, board encoder, and inference helpers. It preserves both alpha-beta and batched beam-search experiments; the UCI engine uses the shared Python search with the new evaluator.',points:['L4 SE-ResNet checkpoint and architecture included','CUDA inference when available; CPU also supported','Experimental search_l4.py and beam_search_l4.py','Training source preserved in kittenfishtraining/v0.5'],repo:'kittenfishv0.5'},{name:'Native thinking.',label:'v1 / C++17 + INCREMENTAL NNUE',text:'The current main engine moves search, legal moves, and incremental NNUE evaluation into C++17. The default model comes from a 100M-position training run, downloaded with a verified checksum during setup.',points:['Principal variation search and bounded transposition table','Incremental accumulators with per-ply independent states','UCI search worker responds to stop while thinking','Original Python search preserved on legacy/python-search'],repo:'kittenfishv1'}];
const panel=document.querySelector('#version-panel');const tabs=[...document.querySelectorAll('[data-version]')];function selectVersion(index,focus=false){const v=versions[index];tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',String(i===index));tab.tabIndex=i===index?0:-1});panel.setAttribute('aria-labelledby',tabs[index].id);panel.innerHTML=`<div><p class="eyebrow">${v.label}</p><h3>${v.name}</h3><p>${v.text}</p><a class="text-link" href="https://github.com/crazykitten43/${v.repo}">Explore ${v.repo} ↗</a></div><ul>${v.points.map(p=>`<li>${p}</li>`).join('')}</ul>`;if(focus)tabs[index].focus()}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectVersion(i));tab.addEventListener('keydown',e=>{let next=i;if(e.key==='ArrowRight')next=(i+1)%3;else if(e.key==='ArrowLeft')next=(i+2)%3;else if(e.key==='Home')next=0;else if(e.key==='End')next=2;else return;e.preventDefault();selectVersion(next,true)})});selectVersion(0);
const rows=['r.bqkbnr','pppp.ppp','..n.....','....p...','....P...','.....N..','PPPP.PPP','RNBQKB.R'];const pieces={r:'♜',n:'♞',b:'♝',q:'♛',k:'♚',p:'♟',R:'♜',N:'♞',B:'♝',Q:'♛',K:'♚',P:'♟'};const board=document.querySelector('#board');rows.forEach((row,r)=>[...row].forEach((p,c)=>{const square=document.createElement('span');square.className=`square ${(r+c)%2?'dark':''} ${p!=='.'&&p===p.toUpperCase()?'piece-white':'piece-black'}`;square.textContent=pieces[p]||'';square.setAttribute('aria-hidden','true');board.append(square)}));
const repos=[['kittenfishv0','01 / ENGINE','CNN evaluator, checkpoint, Python search, and UCI.'],['kittenfishv0.5','02 / ENGINE','L4 SE-ResNet inference and search experiments.'],['kittenfishv1','03 / CURRENT ENGINE','Native C++ search and incremental NNUE evaluation.'],['kittenfishtraining','04 / TRAINING','Training code for v0, v0.5, and v1; dataset conversion and tests.'],['kittenfishdata','05 / DATA','The positions_100k.csv.gz dataset used in the documented diagnosis.'],['kittenfishnnue','06 / MODEL HISTORY','Earlier 500k model release; training has moved to kittenfishtraining.'],['kittenfishfullstack','07 / ORIGINAL HISTORY','Repository index and the original files in Git history.']];document.querySelector('#repositories').innerHTML=repos.map(([name,tag,desc])=>`<article class="repo"><span>${tag}</span><h3>${name}</h3><p>${desc}</p><a href="https://github.com/crazykitten43/${name}">Browse source ↗</a></article>`).join('');document.querySelector('#copy').addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText(document.querySelector('#commands').textContent);status.textContent='Commands copied.'}catch{status.textContent='Select and copy the commands above.'}});
